a=list(map(int,DATA.split()))
n=len(a)
assert n==2*H==2048
assert all(0<=x<=E for x in a)
assert sum(a)==H*E
C={k:sum(a[i]*(E-a[i-k]) for i in range(max(0,k),min(n,n+k)))
   for k in range(-n,n+1)}
assert len(C)==4097 and C[-n]==C[n]==0
peak=max(C.values())
active=[k for k,value in C.items() if value==peak]
U=F(peak,H*E*E)
V=F(sum(abs(x-y) for x,y in zip(a,a[1:])),E)
assert U==F(1247990868533174455263346437,3276800000000000000000000000)
assert V==F(499783679610151,16000000000000)
assert active==[-295,295]
margin=min(peak-value for value in C.values() if value<peak)
assert margin==117785782030754

def literal(t):
    # Integrate on the actual common partition of the two shifted grids.
    cuts=sorted({F(i,H) for i in range(n+1)}|{F(i,H)+t for i in range(n+1)})
    total=F(0)
    for left,right in zip(cuts,cuts[1:]):
        mid=(left+right)/2
        x,y=mid,mid-t
        i=(x*H).__floor__();j=(y*H).__floor__()
        if 0<=i<n and 0<=j<n:
            total+=(right-left)*F(a[i]*(E-a[j]),E*E)
    return total

samples=(F(-5,2),F(-295,H)-F(1,3*H),F(-295,H),F(-1,3),
         F(0),F(1,3),F(295,H),F(295,H)+F(1,3*H),F(5,2))
for t in samples:
    k=(H*t).__floor__();lam=H*t-k
    interpolation=((1-lam)*C.get(k,0)+lam*C.get(k+1,0))/(H*E*E)
    assert literal(t)==interpolation<=U
assert F(380856588297477,10**15)<U<F(380856588297478,10**15)
print('HEIGHTS',n,'EXACT_MASS',F(sum(a),H*E),'BOX_PASS',True)
print('SIGNED_EVENTS',len(C),'ACTIVE_LAGS',[str(F(k,H)) for k in active])
print('INACTIVE_NUMERATOR_MARGIN',margin,'EVENT_DENOMINATOR',H*E*E)
print('UPPER',U)
print('OWN_INTERNAL_VARIATION',V)
print('LITERAL_SHIFTED_GRID_CHECKS',len(samples))
print('PASS: explicit physical witness; all signed real lags via affine interpolation')
u=resource.getrusage(resource.RUSAGE_SELF)
print('CPU',u.ru_utime+u.ru_stime,'WALL',time.monotonic()-started,'RSS_KiB',u.ru_maxrss)
